const SETTINGS_SCRIPT=`(function(){var s=localStorage.getItem('gh-theme')||'auto';var d=window.matchMedia('(prefers-color-scheme: dark)').matches;document.documentElement.setAttribute('data-theme',s==='auto'?(d?'dark':'light'):s);})();function initTheme(){var s=localStorage.getItem('gh-theme')||'auto';var d=window.matchMedia('(prefers-color-scheme: dark)').matches;document.documentElement.setAttribute('data-theme',s==='auto'?(d?'dark':'light'):s);}function setTheme(v){localStorage.setItem('gh-theme',v);initTheme();}function formatSize(b){if(!b||b===0)return '0 KB';var u=localStorage.getItem('gh-size-unit')||'auto',kb=b/1024,mb=kb/1024,gb=mb/1024;if(u==='kb')return kb.toFixed(1)+' KB';if(u==='mb')return mb.toFixed(1)+' MB';if(gb>=0.9)return gb.toFixed(1)+' GB';if(mb>=1)return mb.toFixed(1)+' MB';return kb.toFixed(1)+' KB';}function formatTime(t){var d=new Date(t),n=new Date(),df=n-d,m=Math.floor(df/60000),h=Math.floor(m/60),ds=Math.floor(h/24),f=localStorage.getItem('gh-time-format')||'auto';if(f==='auto'){if(m<1)return '刚刚';if(m<60)return m+'分钟前';if(h<24)return h+'小时前';if(ds<30)return ds+'天前';if(ds<365)return Math.floor(ds/30)+'个月前';return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0')+' '+String(d.getHours()).padStart(2,'0')+':'+String(d.getMinutes()).padStart(2,'0');}var Y=d.getFullYear(),M=String(d.getMonth()+1).padStart(2,'0'),D=String(d.getDate()).padStart(2,'0'),H=d.getHours(),Mi=String(d.getMinutes()).padStart(2,'0');if(f==='24h')return Y+'-'+M+'-'+D+' '+String(H).padStart(2,'0')+':'+Mi;var ap=H>=12?'PM':'AM',h12=H%12;if(h12===0)h12=12;return Y+'-'+M+'-'+D+' '+h12+':'+Mi+' '+ap;}function injectSettingsWidget(){if(document.getElementById('settings-gear'))return;var gear=document.createElement('div');gear.id='settings-gear';gear.innerHTML='⚙️';gear.onclick=function(e){e.stopPropagation();var d=document.getElementById('settings-dropdown');d.style.display=d.style.display==='block'?'none':'block';};var dropdown=document.createElement('div');dropdown.id='settings-dropdown';dropdown.innerHTML='<div class="setting-item"><label>界面主题</label><select id="gearTheme"><option value="auto">跟随系统</option><option value="light">浅色</option><option value="dark">深色</option></select></div><div class="setting-item"><label>文件大小单位</label><select id="gearSize"><option value="auto">智能换算</option><option value="mb">MB</option><option value="kb">KB</option></select></div><div class="setting-item"><label>时间格式</label><select id="gearTime"><option value="auto">智能相对时间</option><option value="24h">24小时制</option><option value="12h">12小时制</option></select></div><div class="setting-item"><label>上传默认路径</label><select id="gearUploadDefault"><option value="on">开启（自动填充当前目录）</option><option value="off">关闭（手动输入完整路径）</option></select></div>';document.body.appendChild(gear);document.body.appendChild(dropdown);document.getElementById('gearTheme').value=localStorage.getItem('gh-theme')||'auto';document.getElementById('gearSize').value=localStorage.getItem('gh-size-unit')||'auto';document.getElementById('gearTime').value=localStorage.getItem('gh-time-format')||'auto';document.getElementById('gearUploadDefault').value=localStorage.getItem('gh-upload-default')||'on';document.getElementById('gearTheme').onchange=function(){setTheme(this.value);};document.getElementById('gearSize').onchange=function(){localStorage.setItem('gh-size-unit',this.value);applySettings();};document.getElementById('gearTime').onchange=function(){localStorage.setItem('gh-time-format',this.value);applySettings();};document.getElementById('gearUploadDefault').onchange=function(){localStorage.setItem('gh-upload-default',this.value);location.reload();};document.addEventListener('click',function(e){var d=document.getElementById('settings-dropdown');if(d&&d.style.display==='block'&&!d.contains(e.target)&&e.target.id!=='settings-gear'){d.style.display='none';}});}function applySettings(){initTheme();injectSettingsWidget();document.querySelectorAll('[data-size]').forEach(e=>e.innerText=formatSize(parseInt(e.getAttribute('data-size'))));document.querySelectorAll('[data-time]').forEach(e=>e.innerText=formatTime(e.getAttribute('data-time')));}`;
const UPLOAD_SCRIPT=`function uploadFileWithProgress(u,f,cb){return new Promise((res,rej)=>{var x=new XMLHttpRequest();x.open('POST',u);x.setRequestHeader('Content-Type','application/octet-stream');x.upload.onprogress=e=>{if(e.lengthComputable)cb(Math.round((e.loaded/e.total)*100));};x.onload=()=>{if(x.status>=200&&x.status<300){try{res(JSON.parse(x.responseText));}catch(e){res(x.responseText);}}else rej(new Error('上传失败: '+x.statusText));};x.onerror=()=>rej(new Error('网络错误'));x.send(f);});}async function uploadFilesSequentially(files,o,r,rid,st,btn){for(var i=0;i<files.length;i++){st.innerText='正在上传第 '+(i+1)+'/'+files.length+' 个文件 (0%)';await uploadFileWithProgress('/api/release/upload_asset?owner='+o+'&repo='+r+'&release_id='+rid+'&file_name='+encodeURIComponent(files[i].name),files[i],p=>st.innerText='正在上传第 '+(i+1)+'/'+files.length+' 个文件 ('+p+'%)');}st.innerText='全部上传成功！';if(btn){btn.disabled=false;btn.innerText='发布版本';}setTimeout(()=>location.reload(),1000);}`;
function isProxiable(h){if(!h)return false;const l=h.toLowerCase();if(PROXY_HOSTS.has(l)||l===MAIN_HOST)return true;if(l.endsWith('.github.com')||l.endsWith('.githubusercontent.com'))return true;if(GITHUB_S3_RE.test(l))return true;return false;}
