function cleanRequestHeaders(r,at){const h=new Headers(r.headers);['host','accept-encoding','cookie','origin','expect','transfer-encoding','connection','proxy-connection','cf-connecting-ip','cf-ray','cf-visitor','cf-worker','cdn-loop','x-forwarded-for','x-forwarded-proto','x-real-ip'].forEach(x=>h.delete(x));if(at)h.set('Authorization',`Bearer ${at}`);const ua=h.get('user-agent');if(!ua||/^cloudflare/i.test(ua))h.set('user-agent',USER_AGENT);if(!h.has('accept'))h.set('accept','*/*');return h;}
