      if(path==='/admin/api/config'&&request.method==='POST'){const t=getCookie(request,'admin_session');if(!(t&&(await env.SESSIONS_KV.get('admin_sess_'+t))))return new Response('Unauthorized',{status:401});const b=await request.json();await env.SESSIONS_KV.put('site_config',JSON.stringify(b));await addLog(env,'修改站点配置','Admin',JSON.stringify(b));return new Response(JSON.stringify({success:true}),{status:200,headers:{'Content-Type':'application/json'}});}
      if(path==='/admin/api/reset_config'&&request.method==='POST'){const t=getCookie(request,'admin_session');if(!(t&&(await env.SESSIONS_KV.get('admin_sess_'+t))))return new Response('Unauthorized',{status:401});const def={maintenance:false,announcement:'',enableRepoCreate:true,enableRepoDelete:true,enableReleaseUpload:true,adminSessionTtl:7,userSessionTtl:3};await env.SESSIONS_KV.put('site_config',JSON.stringify(def));await addLog(env,'恢复默认配置','Admin',JSON.stringify(def));return new Response(JSON.stringify({success:true}),{status:200,headers:{'Content-Type':'application/json'}});}
      if(path==='/admin/api/force_logout'&&request.method==='POST'){const t=getCookie(request,'admin_session');if(!(t&&(await env.SESSIONS_KV.get('admin_sess_'+t))))return new Response('Unauthorized',{status:401});const type=url.searchParams.get('type')||'all';if(type==='users'){const list=await env.SESSIONS_KV.list({prefix:'sess_'});for(const k of list.keys)await env.SESSIONS_KV.delete(k.name);}else if(type==='admins'){const list=await env.SESSIONS_KV.list({prefix:'admin_sess_'});for(const k of list.keys)await env.SESSIONS_KV.delete(k.name);}await addLog(env,'强制下线','Admin','执行了 '+type+' 类型下线');let headers={'Content-Type':'application/json'};if(type==='admins')headers['Set-Cookie']='admin_session=; HttpOnly; Path=/; Max-Age=0';return new Response(JSON.stringify({success:true}),{status:200,headers});}
