      const owner = url.searchParams.get('owner'), repo = url.searchParams.get('repo'), release_id = url.searchParams.get('release_id'), file_name = url.searchParams.get('file_name');
      try { const r = await fetch(`https://uploads.github.com/repos/${owner}/${repo}/releases/${release_id}/assets?name=${encodeURIComponent(file_name)}`, { method: 'POST', headers: { 'Authorization': `Bearer ${accessToken}`, 'User-Agent': USER_AGENT, 'Content-Type': 'application/octet-stream', 'Content-Length': request.headers.get('Content-Length') || '' }, body: request.body, duplex: 'half' }); if (!r.ok) { const t = await r.text(); throw new Error(`上传失败 (${r.status}): ${t}`); } return new Response(JSON.stringify({ success: true, message: '附件上传成功！' }), { status: 200 }); } catch (e) { return new Response(JSON.stringify({ error: e.message }), { status: 500 }); }
